{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Integrates model-based and model-free Stage 1 values into a single net value using a weighting parameter.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "reward_dependent_perseveration",
      "title": "Reward-Dependent Perseveration",
      "description": "Adds a perseveration bonus to the previously chosen Stage 1 action that differs based on whether the previous trial was rewarded or unrewarded.",
      "params": [
        {
          "name": "pers_win",
          "bounds": [-5, 5]
        },
        {
          "name": "pers_lose",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_action >= 0:\n    if last_reward == 1:\n        q_net[last_action] += pers_win\n    elif last_reward == 0:\n        q_net[last_action] += pers_lose",
      "expressible_in_slots": true
    },
    {
      "name": "separate_learning_rates",
      "title": "Separate Stage Learning Rates",
      "description": "Uses distinct learning rates for updating Stage 1 and Stage 2 model-free values.",
      "params": [
        {
          "name": "alpha1",
          "bounds": [0, 1]
        },
        {
          "name": "alpha2",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha1 * delta_stage1\n\ndelta_stage2 = reward[trial] - q_stage2_mf[state_idx, action_2[trial]]\nq_stage2_mf[state_idx, action_2[trial]] += alpha2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the Stage 1 model-free value using the Stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha1 * lam * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
